/* ══════════════════════════════════════════════════════════
   CHATBOT_FAQ — 191 câu hỏi/trả lời thật của Thiện Nga
   Nguồn: FAQ_Chatbot_ThienNga (thu thập 2026-08-01)
   Dùng bởi assets/chatbot-widget.js
   Mỗi mục: { id, cat, q, v:[biến thể], a, tag }
══════════════════════════════════════════════════════════ */
const CHATBOT_FAQ = [
{id:1,cat:"A",q:"Nhà hàng Thiện Nga là gì, chuyên phục vụ những gì?",v:["Thiện Nga làm dịch vụ gì vậy shop?","Nhà hàng mình chuyên về gì?","Thiện Nga bán gì ạ?"],a:"Dạ, Nhà Hàng Tiệc Cưới Thiện Nga chuyên tổ chức sự kiện – cưới hỏi trọn gói: cho thuê nhà hàng/rạp sự kiện, nấu tiệc, lễ gia tiên, mâm quả, tiệc sinh nhật, bóng kích nổ trang trí, decor theo concept yêu cầu. Ngoài ra quán còn phục vụ các món nhậu bình dân, liên hoan, hội nghị hằng ngày.",tag:"gioi_thieu"},
{id:2,cat:"A",q:"Nhà hàng ở đâu, địa chỉ cụ thể thế nào?",v:["Địa chỉ quán ở đâu vậy ạ?","Cho xin địa chỉ đi ạ","Quán mình ở khu nào Vạn Ninh vậy?"],a:"Dạ, Nhà hàng Thiện Nga tọa lạc tại Thôn Ninh Mã, xã Đại Lãnh, tỉnh Khánh Hòa (khu vực trước đây thuộc thị xã Vạn Ninh). Anh/chị có thể bấm \"Chỉ đường\" trên nhahangthiennga.com hoặc tìm trên Google Maps theo tên \"Nhà Hàng Tiệc Cưới Thiện Nga\".",tag:"dia_chi"},
{id:3,cat:"A",q:"Số điện thoại/hotline liên hệ là gì?",v:["Cho xin số hotline","SĐT đặt tiệc là bao nhiêu?","Liên hệ số nào để tư vấn?"],a:"Dạ anh/chị liên hệ hotline 0965 626 128 để được tư vấn và đặt tiệc trực tiếp. Nhà hàng luôn sẵn sàng hỗ trợ trong giờ hoạt động.",tag:"hotline"},
{id:4,cat:"A",q:"Nhà hàng có website đặt tiệc online không?",v:["Có web đặt bàn online không?","Đặt tiệc qua mạng được không?"],a:"Dạ có ạ, anh/chị tham khảo thực đơn, hình ảnh, giá cả và đặt tiệc online qua nhahangthiennga.com, hoặc nhắn Zalo https://zalo.me/0965626128, hoặc Fanpage Facebook \"Nhà Hàng Tiệc Cưới THIỆN NGA\".",tag:"website"},
{id:5,cat:"A",q:"thienngawedding.com và nhahangthiennga.com có phải cùng 1 nhà hàng không?",v:["2 web này có phải 1 chỗ không?","Sao có 2 website vậy ạ?"],a:"Dạ đây đều là các kênh online của cùng một cơ sở Thiện Nga tại Thôn Ninh Mã, xã Đại Lãnh, Khánh Hòa. nhahangthiennga.com tập trung giới thiệu dịch vụ nấu tiệc tại gia, tiệc cưới trọn gói và 40 thực đơn cưới; thienngawedding.com giới thiệu thêm không gian quán ăn/quán nhậu tại chỗ. Cùng 1 hotline sẽ tư vấn đầy đủ cả hai hình thức.",tag:"phan_biet_website"},
{id:6,cat:"A",q:"Nhà hàng mở cửa giờ nào, có nghỉ ngày nào không?",v:["Giờ mở cửa thế nào ạ?","Chủ nhật có mở không?"],a:"Dạ, nhà hàng hoạt động 08:00 – 20:00 tất cả các ngày trong tuần. Riêng giờ tổ chức tiệc cụ thể sẽ theo thỏa thuận khi đặt tiệc.",tag:"gio_mo_cua"},
{id:7,cat:"A",q:"Nhà hàng có bao nhiêu năm kinh nghiệm / uy tín không?",v:["Quán mở lâu chưa ạ?","Có ai đánh giá review chưa?"],a:"Dạ, Thiện Nga là nhà hàng tiệc cưới quen thuộc tại khu vực Vạn Ninh – Khánh Hòa, đã đồng hành cùng rất nhiều cặp đôi và gia đình tổ chức tiệc cưới, tiệc thôi nôi, liên hoan... Anh/chị có thể xem thêm hình ảnh tiệc thực tế trên Fanpage.",tag:"uy_tin"},
{id:8,cat:"A",q:"Nhà hàng có phục vụ cả tiệc cưới lẫn quán nhậu bình dân không?",v:["Vừa làm tiệc cưới vừa bán nhậu hả?","Ngày thường có bán không?"],a:"Dạ đúng ạ, ngoài mảng tổ chức tiệc cưới – sự kiện trọn gói, Thiện Nga còn phục vụ quán nhậu bình dân hằng ngày với các món hải sản, món nhậu quen thuộc, phù hợp gia đình, bạn bè, liên hoan nhỏ.",tag:"quan_nhau"},
{id:9,cat:"A",q:"Nhà hàng có phải cơ sở hộ gia đình hay công ty?",v:["Đây là hộ kinh doanh hay công ty ạ?"],a:"Dạ, Thiện Nga là cơ sở nhà hàng chuyên tổ chức tiệc cưới – sự kiện tại địa phương. Cần hóa đơn, chứng từ cụ thể, em sẽ nhờ bộ phận kế toán hỗ trợ trao đổi trực tiếp qua hotline.",tag:"phap_ly"},
{id:10,cat:"A",q:"Có cần đặt lịch hẹn trước khi đến xem địa điểm không?",v:["Muốn đến xem quán trước có cần hẹn không?","Ghé tham quan trực tiếp được không?"],a:"Dạ được ạ, anh/chị nên nhắn hotline trước để nhà hàng sắp xếp thời gian đón tiếp và tư vấn chu đáo hơn.",tag:"hen_xem_dia_diem"},
{id:11,cat:"A",q:"Nhà hàng có chỗ để chụp ảnh cưới/pre-wedding không?",v:["Có cho chụp hình cưới ở đây không?"],a:"Dạ, không gian nhà hàng và khu vực rạp sự kiện đều được trang trí đẹp, phù hợp chụp ảnh lưu niệm trong ngày tiệc. Muốn chụp pre-wedding riêng, vui lòng liên hệ trước.",tag:"chup_anh"},
{id:12,cat:"A",q:"Nhà hàng có fanpage nào để xem thêm hình ảnh?",v:["Có Facebook không ạ?","Xem hình tiệc thực tế ở đâu?"],a:"Dạ, anh/chị có thể theo dõi Fanpage \"Nhà Hàng Tiệc Cưới THIỆN NGA\" để xem hình ảnh, video tiệc thực tế và cập nhật ưu đãi mới nhất.",tag:"fanpage"},
{id:13,cat:"A",q:"Ai sẽ tư vấn và phụ trách tiệc của mình từ đầu đến cuối?",v:["Có nhân viên riêng phụ trách tiệc của em không?"],a:"Dạ có ạ, mọi tiệc sẽ có nhân viên tư vấn/điều phối phụ trách xuyên suốt từ khâu lên thực đơn, trang trí đến ngày diễn ra tiệc.",tag:"nhan_su_phu_trach"},
{id:14,cat:"B",q:"Muốn đặt tiệc cưới thì cần chuẩn bị/cung cấp thông tin gì?",v:["Đặt tiệc cần thông tin gì?","Em muốn đặt bàn tiệc cưới thì làm sao?"],a:"Dạ anh/chị vui lòng cho em xin: ngày giờ tổ chức dự kiến, số lượng bàn/khách mời, loại tiệc, thực đơn hoặc mức giá mong muốn và số điện thoại liên hệ. Nhà hàng sẽ tư vấn chi tiết và giữ lịch cho mình.",tag:"quy_trinh_dat_tiec"},
{id:15,cat:"B",q:"Cần đặt tiệc trước bao lâu thì được?",v:["Đặt trước mấy tháng vậy?","Sát ngày cưới còn đặt được không?"],a:"Dạ, nên đặt tiệc trước khoảng 1–3 tháng, đặc biệt vào mùa cưới cao điểm (cuối năm, đầu năm). Trường hợp đặt gấp, cứ liên hệ hotline để kiểm tra lịch trống.",tag:"thoi_gian_dat_truoc"},
{id:16,cat:"B",q:"Làm sao để biết ngày mình chọn còn trống hay đã có người đặt?",v:["Ngày 20/12 còn trống không ạ?"],a:"Dạ anh/chị cho em xin ngày giờ dự kiến tổ chức tiệc, em sẽ kiểm tra lịch và phản hồi ngay trong hôm nay.",tag:"kiem_tra_lich_trong"},
{id:17,cat:"B",q:"Đặt tiệc qua điện thoại có được giữ chỗ luôn không hay phải đặt cọc mới giữ?",v:["Nhắn tin đặt trước có giữ bàn không?"],a:"Dạ, nhà hàng sẽ tạm giữ lịch khi nhắn tin/gọi điện đặt trước, tuy nhiên để chắc chắn giữ chỗ (đặc biệt ngày đẹp, cao điểm) nên hoàn tất đặt cọc theo hướng dẫn.",tag:"giu_cho"},
{id:18,cat:"B",q:"Số lượng bàn tối thiểu/tối đa để nhận tổ chức tiệc là bao nhiêu?",v:["Đặt ít bàn có nhận không?","Tối đa tổ chức được bao nhiêu bàn?"],a:"Dạ nhà hàng nhận tổ chức tiệc linh hoạt theo nhu cầu, từ tiệc gia đình vài bàn đến tiệc cưới quy mô lớn tại khu vực rạp sự kiện ngoài trời.",tag:"so_luong_ban"},
{id:19,cat:"B",q:"Có thể thay đổi số lượng bàn sau khi đã đặt không?",v:["Đặt rồi có tăng thêm bàn được không?"],a:"Dạ được ạ, anh/chị có thể điều chỉnh số bàn tăng/giảm, nên báo trước ít nhất 2–3 ngày để nhà hàng chuẩn bị nguyên liệu và sắp xếp không gian phù hợp.",tag:"thay_doi_so_ban"},
{id:20,cat:"B",q:"Đặt tiệc cưới và tiệc sinh nhật/liên hoan quy trình có khác nhau không?",v:["Đặt tiệc sinh nhật có giống đặt tiệc cưới không?"],a:"Dạ quy trình tương tự nhau: cho ngày giờ, số bàn, loại tiệc và thực đơn mong muốn, nhà hàng sẽ báo giá và tư vấn trang trí phù hợp theo từng loại tiệc.",tag:"quy_trinh_khac"},
{id:21,cat:"B",q:"Có thể đặt tiệc vào các ngày lễ, Tết không?",v:["Tết có nhận tiệc không?"],a:"Dạ có ạ, tuy nhiên vào ngày lễ Tết lượng khách đặt tiệc thường rất đông, nên liên hệ đặt lịch càng sớm càng tốt.",tag:"dat_tiec_ngay_le"},
{id:22,cat:"B",q:"Có thể vừa đặt tiệc cưới vừa đặt luôn trang trí, mâm quả, gia tiên trong 1 lần không?",v:["Đặt trọn gói 1 lần luôn được không?"],a:"Dạ được ạ, đây chính là thế mạnh của Thiện Nga – dịch vụ cưới hỏi trọn gói gồm nhà hàng, nấu tiệc, rạp sự kiện, lễ gia tiên, mâm quả, decor theo concept yêu cầu.",tag:"goi_tron_goi"},
{id:23,cat:"B",q:"Sau khi đặt tiệc, bao lâu thì nhà hàng xác nhận lại thông tin?",v:["Đặt xong có ai gọi lại xác nhận không?"],a:"Dạ, sau khi cung cấp thông tin và đặt cọc, nhân viên phụ trách sẽ liên hệ xác nhận chi tiết và nhắc lịch trước ngày tổ chức.",tag:"xac_nhan_dat_tiec"},
{id:24,cat:"B",q:"Có thể đặt tiệc giúp người thân ở xa không?",v:["Con đặt giúp ba mẹ ở xa được không?"],a:"Dạ được ạ, có thể trao đổi và đặt tiệc từ xa qua điện thoại/Facebook, nhà hàng sẽ gửi hình ảnh không gian, thực đơn tham khảo qua website.",tag:"dat_ho_tu_xa"},
{id:25,cat:"B",q:"Nhà hàng có nhận nấu tiệc tại nhà khách không?",v:["Có nấu tiệc tại nhà không ạ?"],a:"Dạ, nhà hàng có nhận nấu tiệc và phục vụ lưu động tùy khu vực và quy mô, vui lòng liên hệ hotline để trao đổi cụ thể địa điểm, số lượng bàn.",tag:"nau_tiec_luu_dong"},
{id:26,cat:"B",q:"Có cần đặt tiệc bằng văn bản/hợp đồng không?",v:["Có ký hợp đồng không ạ?"],a:"Dạ với tiệc quy mô lớn, nhà hàng có thể lập phiếu đặt tiệc/biên nhận ghi rõ thông tin thực đơn, số bàn, giá tiền, tiền cọc để hai bên yên tâm.",tag:"hop_dong"},
{id:27,cat:"C",q:"Giá mỗi bàn tiệc cưới là bao nhiêu?",v:["1 bàn tiệc cưới giá nhiêu vậy?","Đặt 1 bàn tốn bao nhiêu tiền?","giá 1 bàn 10 người bao nhiêu"],a:"Dạ giá bàn còn tùy thuộc vào anh/chị chọn dịch vụ nào bên em ạ — anh/chị đãi tại nhà, dựng rạp, hay đãi tại nhà hàng? Nếu theo 40 thực đơn cưới trọn gói có sẵn, giá chia 3 mức: 2.200.000đ / 2.300.000đ / 2.400.000đ cho bàn 10 người, mỗi thực đơn gồm 1 khai vị + 3 món chính + 1 lẩu + 1 tráng miệng. Anh/chị cho em xin ngân sách dự kiến để em tư vấn thực đơn phù hợp ạ.",tag:"gia_ban_tiec"},
{id:28,cat:"C",q:"Nhà hàng có báo giá rõ ràng, minh bạch không?",v:["Giá có rõ ràng không hay giấu giá?"],a:"Dạ nhà hàng luôn báo giá minh bạch – quán không giấu giá. Chỉ cần cho biết ngân sách, nhà hàng sẽ lên thực đơn phù hợp, không dư không thiếu.",tag:"minh_bach_gia"},
{id:29,cat:"C",q:"Giá các món ăn lẻ trong thực đơn quán nhậu dao động khoảng bao nhiêu?",v:["Món ăn giá bao nhiêu?"],a:"Dạ các món khai vị/gỏi/salad dao động khoảng 49.000đ – 119.000đ/món; các món hải sản chế biến như mực, tôm, hàu... khoảng 119.000đ – 199.000đ/món; riêng hải sản tươi sống được tính theo Kg hoặc giá thị trường (TTG) tại thời điểm đặt.",tag:"gia_mon_le"},
{id:30,cat:"C",q:"Giá có bao gồm bàn ghế, khăn trải bàn, chén đũa không?",v:["Giá đã gồm bàn ghế chưa?"],a:"Dạ giá tiệc thường đã bao gồm bàn ghế, khăn trải bàn, chén đũa phục vụ cơ bản. Yêu cầu thêm về decor, khăn ghế theo concept riêng sẽ được báo giá phụ thu riêng.",tag:"gia_bao_gom_gi"},
{id:31,cat:"C",q:"Giá tiệc có bao gồm nước ngọt, bia, rượu không?",v:["Nước uống có tính riêng không?"],a:"Dạ tùy theo thỏa thuận, nước ngọt/trà đá thường tính kèm hoặc tính riêng theo số lượng sử dụng thực tế; bia, rượu thường tính riêng theo đơn giá từng loại.",tag:"gia_nuoc_uong"},
{id:32,cat:"C",q:"Có phụ thu gì thêm ngoài giá bàn không?",v:["Có phát sinh phí gì không?"],a:"Dạ tùy theo yêu cầu cụ thể (âm thanh ánh sáng, MC, trang trí đặc biệt, phục vụ ngoài giờ...) có thể phát sinh phụ thu tương ứng. Nhà hàng sẽ báo trước đầy đủ để anh/chị chủ động ngân sách.",tag:"phu_thu"},
{id:33,cat:"C",q:"Đặt càng nhiều bàn có được giảm giá không?",v:["Đặt tiệc lớn có ưu đãi không?"],a:"Dạ với tiệc số lượng bàn lớn, nhà hàng thường có chính sách hỗ trợ/ưu đãi thêm (tùy thời điểm và chương trình khuyến mãi hiện hành). Anh/chị liên hệ hotline để được tư vấn mức ưu đãi cụ thể.",tag:"chiet_khau_so_luong"},
{id:34,cat:"C",q:"Giá có thay đổi theo mùa cưới cao điểm không?",v:["Mùa cưới giá có tăng không?"],a:"Dạ giá món ăn cơ bản thường ổn định, tuy nhiên vào mùa cao điểm một số hải sản tươi sống theo giá thị trường (TTG) có thể biến động. Nhà hàng sẽ báo giá chính xác tại thời điểm đặt tiệc.",tag:"gia_theo_mua"},
{id:35,cat:"C",q:"Có thể xin bảng giá/menu chi tiết để tham khảo trước không?",v:["Cho em xin bảng giá được không?"],a:"Dạ được ạ, xem thực đơn và giá tham khảo tại mục Thực Đơn trên nhahangthiennga.com, hoặc nhắn hotline để gửi bảng giá chi tiết theo nhu cầu.",tag:"xin_bang_gia"},
{id:36,cat:"C",q:"Có gói tiệc trọn gói theo mức giá cố định không?",v:["Có set menu theo giá cố định không?"],a:"Dạ có ạ, nhà hàng có các gợi ý thực đơn (set menu) theo từng mức ngân sách phổ biến, đồng thời vẫn linh hoạt điều chỉnh món theo sở thích và ngân sách riêng.",tag:"set_menu_co_dinh"},
{id:37,cat:"C",q:"Giá tiệc trẻ em/mâm cỗ chay có khác giá thường không?",v:["Trẻ em có giảm giá không?"],a:"Dạ nhà hàng có thể chuẩn bị suất ăn trẻ em hoặc mâm cỗ chay riêng theo yêu cầu với mức giá tương ứng.",tag:"gia_tre_em_chay"},
{id:38,cat:"C",q:"Nếu ngân sách hạn chế thì nhà hàng có tư vấn thực đơn tiết kiệm không?",v:["Ngân sách ít có làm tiệc được không?"],a:"Dạ được ạ, đúng theo phương châm \"không giấu giá – nói ngân sách, lên thực đơn phù hợp\", dù ngân sách cao hay vừa phải, nhà hàng đều tư vấn thực đơn cân đối, đúng số tiền đưa ra, không phát sinh thêm.",tag:"tu_van_ngan_sach"},
{id:39,cat:"C",q:"Thanh toán giá tiệc là theo số bàn thực tế hay theo số bàn đặt trước?",v:["Đặt dư bàn mà không dùng hết có bị tính tiền không?"],a:"Dạ thông thường sẽ thanh toán theo số bàn đã xác nhận đặt trước, nếu có thay đổi số bàn thực tế nên báo sớm để được điều chỉnh hợp lý.",tag:"thanh_toan_theo_ban"},
{id:40,cat:"D",q:"Thực đơn nhà hàng có những món gì?",v:["Menu có gì vậy ạ?","Quán có món gì ngon?"],a:"Dạ thực đơn của Thiện Nga rất đa dạng: các món hải sản (mực, tôm, cá, hàu...), gỏi/salad, bê thui tái chanh, chả giò hải sản và nhiều món khác. Xem đầy đủ tại mục Thực Đơn trên nhahangthiennga.com.",tag:"menu_tong_quan"},
{id:41,cat:"D",q:"Có món đặc sản/signature riêng của quán không?",v:["Món nào ngon nhất quán vậy?"],a:"Dạ một số món được khách yêu thích gồm mực lá nướng muối ớt, bê thui tái chanh, gỏi hải sản củ hủ dừa và các món hải sản tươi theo giá thị trường.",tag:"mon_dac_san"},
{id:42,cat:"D",q:"Hải sản ở đây có tươi sống không, nguồn gốc từ đâu?",v:["Hải sản có tươi không ạ?"],a:"Dạ nhà hàng ở khu vực ven biển Vạn Ninh – Khánh Hòa nên hải sản được ưu tiên nguồn tươi sống theo ngày, đảm bảo chất lượng cho các món chế biến và tiệc cưới.",tag:"nguon_goc_hai_san"},
{id:43,cat:"D",q:"Có thể tự chọn món để ghép thành thực đơn riêng không?",v:["Em muốn tự chọn món được không?"],a:"Dạ được ạ, hoàn toàn có thể tự chọn món theo sở thích để ghép thực đơn riêng, hoặc chọn nhanh theo gợi ý set có sẵn rồi điều chỉnh thêm/bớt món.",tag:"tu_chon_mon"},
{id:44,cat:"D",q:"Có thể đổi món trong thực đơn đã chọn trước ngày tiệc không?",v:["Chọn rồi có đổi lại được không?"],a:"Dạ được ạ, nên báo thay đổi trước ít nhất 2–3 ngày để nhà hàng kịp chuẩn bị nguyên liệu tươi ngon nhất.",tag:"doi_mon_truoc_ngay"},
{id:45,cat:"D",q:"Nhà hàng có phục vụ món chay không?",v:["Có món chay không ạ?"],a:"Dạ có ạ, nhà hàng có thể chuẩn bị mâm/suất ăn chay riêng cho khách có nhu cầu, vui lòng báo trước số lượng suất chay khi đặt tiệc.",tag:"mon_chay"},
{id:46,cat:"D",q:"Có thực đơn riêng cho trẻ em không?",v:["Có suất ăn cho bé không?"],a:"Dạ có ạ, nhà hàng có thể chuẩn bị suất ăn phù hợp khẩu vị trẻ em (ít cay, dễ ăn) theo yêu cầu.",tag:"mon_tre_em"},
{id:47,cat:"D",q:"Nếu khách bị dị ứng hải sản thì có thực đơn thay thế không?",v:["Khách dị ứng hải sản thì sao?"],a:"Dạ vui lòng báo trước cho nhà hàng biết khách nào bị dị ứng để đầu bếp chuẩn bị món thay thế phù hợp, đảm bảo an toàn.",tag:"di_ung_thuc_pham"},
{id:48,cat:"D",q:"Số món trong 1 bàn tiệc cưới thường là bao nhiêu món?",v:["1 bàn có mấy món ạ?"],a:"Dạ tùy theo mức giá và yêu cầu, một bàn tiệc cưới thường có khoảng 6–10 món (khai vị, món chính, canh/súp, xào, tráng miệng...).",tag:"so_mon_1_ban"},
{id:49,cat:"D",q:"Có thể xem hình ảnh món ăn thực tế trước khi đặt không?",v:["Có hình món ăn thật không?"],a:"Dạ có ạ, xem hình ảnh từng món tại mục Thực Đơn trên website hoặc trên Fanpage Facebook.",tag:"hinh_anh_mon_an"},
{id:50,cat:"D",q:"Món tính theo Kg/giá thị trường (TTG) là như thế nào?",v:["TTG là gì vậy ạ?"],a:"Dạ một số hải sản tươi sống có giá biến động theo thị trường từng ngày nên được ghi là \"Tính theo Kg/TTG\". Khi đặt tiệc, nhà hàng sẽ báo giá chính xác tại thời điểm đặt.",tag:"giai_thich_TTG"},
{id:51,cat:"D",q:"Nhà hàng có phục vụ đồ uống không hay khách tự mang?",v:["Bia rượu quán có bán không?"],a:"Dạ nhà hàng có phục vụ đầy đủ bia, nước ngọt, nước suối theo yêu cầu. Khách muốn tự mang riêng thì trao đổi trước với nhà hàng.",tag:"do_uong"},
{id:52,cat:"D",q:"Có thể nếm thử món trước khi đặt tiệc số lượng lớn không?",v:["Cho nếm thử món trước được không?"],a:"Dạ với tiệc số lượng lớn, có thể liên hệ trước để nhà hàng sắp xếp cho nếm thử một số món chính.",tag:"nem_thu_mon"},
{id:53,cat:"D",q:"Món ăn có thể mang về (take-away) không?",v:["Đặt món mang về được không?"],a:"Dạ có ạ, nhà hàng có phục vụ hình thức mang về/takeaway cho một số món.",tag:"mang_ve"},
{id:54,cat:"D",q:"Đồ ăn thừa sau tiệc khách có được mang về không?",v:["Đồ ăn dư có gói mang về được không?"],a:"Dạ được ạ, nhà hàng sẵn sàng hỗ trợ đóng gói phần thức ăn còn dư sau tiệc để khách mời mang về nếu gia đình có nhu cầu.",tag:"do_an_thua"},
{id:55,cat:"D",q:"Nhà hàng có tư vấn thực đơn theo phong tục vùng miền không?",v:["Làm tiệc theo phong tục miền Bắc được không?"],a:"Dạ nhà hàng linh hoạt tư vấn thực đơn phù hợp với phong tục, khẩu vị từng vùng miền theo yêu cầu của gia đình.",tag:"thuc_don_vung_mien"},
{id:56,cat:"E",q:"Đặt tiệc có cần đặt cọc không, đặt cọc bao nhiêu?",v:["Cọc bao nhiêu tiền vậy ạ?","Có bắt buộc đặt cọc không?"],a:"Dạ để giữ chỗ chắc chắn, đặc biệt vào ngày cao điểm, nhà hàng có áp dụng đặt cọc giữ bàn. Mức cọc cụ thể tùy theo quy mô tiệc, liên hệ hotline để được hướng dẫn đặt cọc qua chuyển khoản/QR.",tag:"muc_dat_coc"},
{id:57,cat:"E",q:"Đặt cọc bằng cách nào, có thể chuyển khoản không?",v:["Chuyển khoản đặt cọc được không?"],a:"Dạ được ạ, nhà hàng hỗ trợ đặt cọc qua chuyển khoản/quét mã QR rất nhanh gọn.",tag:"chuyen_khoan_qr"},
{id:58,cat:"E",q:"Nếu hủy tiệc thì tiền cọc có được hoàn lại không?",v:["Hủy tiệc có mất cọc không?"],a:"Dạ chính sách hoàn/không hoàn cọc khi hủy tiệc sẽ tùy thời điểm hủy trước ngày tổ chức bao lâu. Anh/chị liên hệ hotline để được tư vấn cụ thể chính sách áp dụng.",tag:"hoan_coc_khi_huy"},
{id:59,cat:"E",q:"Thanh toán phần còn lại vào lúc nào, trước hay sau tiệc?",v:["Thanh toán hết khi nào ạ?"],a:"Dạ thông thường phần còn lại sẽ được thanh toán vào cuối buổi tiệc hoặc theo thỏa thuận cụ thể lúc đặt bàn.",tag:"thoi_diem_thanh_toan"},
{id:60,cat:"E",q:"Có thể thanh toán bằng tiền mặt không hay chỉ chuyển khoản?",v:["Trả tiền mặt được không?"],a:"Dạ nhà hàng nhận cả tiền mặt và chuyển khoản/QR, chọn hình thức nào thuận tiện nhất đều được.",tag:"hinh_thuc_thanh_toan"},
{id:61,cat:"E",q:"Nhà hàng có xuất hóa đơn VAT không?",v:["Có xuất hóa đơn để không?"],a:"Dạ vui lòng liên hệ trực tiếp hotline để trao đổi về nhu cầu xuất hóa đơn, nhà hàng sẽ hỗ trợ tư vấn cụ thể theo quy định hiện hành.",tag:"hoa_don_vat"},
{id:62,cat:"E",q:"Có thể thanh toán trước một phần rồi trả góp phần còn lại không?",v:["Có cho trả góp không ạ?"],a:"Dạ có thể trao đổi trực tiếp với nhà hàng về việc chia đợt thanh toán (cọc giữ chỗ, thanh toán thêm trước ngày tiệc, tất toán sau tiệc).",tag:"chia_dot_thanh_toan"},
{id:63,cat:"E",q:"Nếu số bàn thực tế ít hơn số đã đặt cọc thì tính tiền thế nào?",v:["Đặt cọc 20 bàn mà chỉ dùng 18 bàn thì sao?"],a:"Dạ nên báo sớm cho nhà hàng trước ngày tiệc để được điều chỉnh và tính toán hợp lý phần chênh lệch.",tag:"chenh_lech_so_ban"},
{id:64,cat:"E",q:"Có được yêu cầu biên nhận/phiếu xác nhận đặt cọc không?",v:["Cọc xong có giấy biên nhận không?"],a:"Dạ có ạ, khi đặt cọc anh/chị sẽ được nhà hàng xác nhận qua tin nhắn/phiếu ghi rõ thông tin ngày tiệc, số bàn và số tiền đã cọc.",tag:"bien_nhan_dat_coc"},
{id:65,cat:"E",q:"Phí phát sinh ngoài dự kiến (thêm bàn, thêm món) thanh toán như thế nào?",v:["Phát sinh thêm bàn trả tiền lúc nào?"],a:"Dạ các khoản phát sinh thêm trong ngày tiệc sẽ được nhân viên ghi nhận và tổng hợp thanh toán cùng lúc quyết toán cuối tiệc.",tag:"thanh_toan_phat_sinh"},
{id:66,cat:"E",q:"Đặt cọc rồi có cần đến tận nơi ký giấy tờ không?",v:["Cọc online có cần lên ký giấy không?"],a:"Dạ với tiệc thông thường, chuyển khoản/cọc online kèm xác nhận thông tin qua tin nhắn là đủ. Tiệc quy mô lớn có thể hẹn gặp trực tiếp để xác nhận thêm nếu cần.",tag:"ky_giay_to"},
{id:67,cat:"F",q:"Nhà hàng có thể chứa tối đa bao nhiêu bàn/khách?",v:["Sức chứa tối đa bao nhiêu bàn?"],a:"Dạ nhà hàng có cả khu vực trong nhà và rạp sự kiện ngoài trời nên có thể linh hoạt bố trí cho tiệc từ quy mô nhỏ đến tiệc cưới lớn. Anh/chị cho biết số khách/bàn dự kiến để em tư vấn khu vực phù hợp nhất.",tag:"suc_chua"},
{id:68,cat:"F",q:"Có khu vực rạp ngoài trời riêng cho tiệc cưới không?",v:["Có dựng rạp ngoài trời không?"],a:"Dạ có ạ, nhà hàng có dịch vụ cho thuê/dựng rạp sự kiện để tổ chức tiệc cưới ngoài trời, kết hợp trang trí theo concept yêu cầu.",tag:"rap_su_kien"},
{id:69,cat:"F",q:"Nhà hàng có tự trang trí (decor) tiệc theo concept yêu cầu không?",v:["Muốn decor theo chủ đề được không?"],a:"Dạ có ạ, nhà hàng nhận trang trí theo concept yêu cầu của gia đình (tông màu, phong cách, hoa trang trí, backdrop cổng cưới...).",tag:"decor_concept"},
{id:70,cat:"F",q:"Có sẵn backdrop/cổng cưới, bàn ký tên, bàn tiếp khách không?",v:["Có cổng hoa cưới không?"],a:"Dạ có ạ, nhà hàng có thể chuẩn bị backdrop, cổng cưới, bàn ký tên, bàn tiếp khách... theo yêu cầu.",tag:"backdrop"},
{id:71,cat:"F",q:"Có hệ thống âm thanh, ánh sáng, sân khấu cho tiệc cưới không?",v:["Có loa đài không ạ?"],a:"Dạ nhà hàng có hỗ trợ âm thanh, ánh sáng và sân khấu cơ bản cho lễ cưới. Cần dàn chuyên nghiệp hơn thì nhà hàng có thể liên kết đơn vị đối tác hỗ trợ thêm.",tag:"am_thanh_anh_sang"},
{id:72,cat:"F",q:"Bóng kích nổ trang trí là dịch vụ như thế nào?",v:["Bóng kích nổ là gì vậy?"],a:"Dạ đây là dịch vụ trang trí bằng bóng bay tạo hiệu ứng (thả bóng, kích nổ bóng...) giúp không gian tiệc thêm lung linh, ấn tượng, thường dùng cho tiệc cưới, sinh nhật.",tag:"bong_kich_no"},
{id:73,cat:"F",q:"Có thể mang trang trí/hoa cưới riêng từ bên ngoài vào không?",v:["Tự mang hoa trang trí vào được không?"],a:"Dạ hoàn toàn có thể tự chuẩn bị hoa/trang trí riêng hoặc thuê đơn vị decor bên ngoài, nhà hàng vẫn hỗ trợ sắp xếp không gian phối hợp.",tag:"mang_decor_ngoai"},
{id:74,cat:"F",q:"Không gian có máy lạnh/điều hòa không hay chỉ có quạt?",v:["Trong nhà có máy lạnh không?"],a:"Dạ khu vực trong nhà hàng có quạt/hệ thống làm mát, khu vực rạp ngoài trời sẽ thoáng mát tự nhiên.",tag:"may_lanh_quat"},
{id:75,cat:"F",q:"Có khu vực riêng để cô dâu chú rể thay đồ, trang điểm không?",v:["Có phòng thay đồ cho cô dâu không?"],a:"Dạ nhà hàng có thể sắp xếp khu vực riêng tư để cô dâu chú rể chuẩn bị, thay trang phục trước giờ lễ.",tag:"phong_chuan_bi"},
{id:76,cat:"F",q:"Nhà hàng có hỗ trợ dọn dẹp sau tiệc không?",v:["Ăn xong ai dọn vậy ạ?"],a:"Dạ nhân viên nhà hàng sẽ phụ trách dọn dẹp sau tiệc, gia đình không cần lo phần này.",tag:"don_dep_sau_tiec"},
{id:77,cat:"F",q:"Có thể xem trước không gian thực tế qua video/hình ảnh không?",v:["Có video quay không gian không?"],a:"Dạ có thể xem hình ảnh và video tiệc cưới thực tế đã tổ chức tại nhà hàng trên Fanpage Facebook và website.",tag:"xem_video_khong_gian"},
{id:78,cat:"F",q:"Nhà hàng có phục vụ tiệc trong nhà khi trời mưa không (dự phòng)?",v:["Mưa thì tiệc ngoài trời sao ạ?"],a:"Dạ nhà hàng luôn có phương án dự phòng khi thời tiết xấu, có thể chuyển một phần hoặc toàn bộ tiệc vào khu vực trong nhà.",tag:"du_phong_troi_mua"},
{id:79,cat:"F",q:"Có chỗ đặt bàn thờ gia tiên tại nhà hàng không nếu tổ chức lễ tại đây?",v:["Làm lễ gia tiên tại nhà hàng được không?"],a:"Dạ tùy theo yêu cầu, nhà hàng có thể hỗ trợ bố trí khu vực làm lễ, tuy nhiên lễ gia tiên truyền thống thường được tổ chức tại nhà riêng, nhà hàng có đội ngũ hỗ trợ chuẩn bị mâm lễ, mâm quả mang đến tận nơi.",tag:"le_gia_tien_tai_nha_hang"},
{id:80,cat:"F",q:"Nhà hàng có chỗ giữ trẻ em/khu vui chơi cho bé không?",v:["Có chỗ chơi cho trẻ con không?"],a:"Dạ hiện khu vực chủ yếu phục vụ không gian tiệc, nếu gia đình có trẻ nhỏ đi cùng có thể trao đổi trước để nhà hàng hỗ trợ sắp xếp bàn/ghế phù hợp.",tag:"khu_vui_choi_tre_em"},
{id:81,cat:"G",q:"Dịch vụ cưới hỏi trọn gói của nhà hàng gồm những gì?",v:["Trọn gói cưới hỏi gồm gì vậy?"],a:"Dạ gói cưới hỏi trọn gói của Thiện Nga gồm: cho thuê nhà hàng/rạp sự kiện, nấu tiệc đãi khách, chuẩn bị lễ gia tiên, mâm quả, trang trí (decor) theo concept yêu cầu, và có thể hỗ trợ thêm bóng kích nổ trang trí.",tag:"goi_tron_goi_chi_tiet"},
{id:82,cat:"G",q:"Mâm quả cưới hỏi có bao nhiêu loại, giá thế nào?",v:["Mâm quả có mấy tráp?"],a:"Dạ nhà hàng nhận chuẩn bị mâm quả theo phong tục vùng miền (5, 6, 7, 9 tráp...) tùy yêu cầu gia đình. Anh/chị cho biết số tráp và phong cách mong muốn để em tư vấn và báo giá cụ thể.",tag:"mam_qua"},
{id:83,cat:"G",q:"Lễ gia tiên nhà hàng hỗ trợ những gì?",v:["Gia tiên gồm những gì vậy?"],a:"Dạ nhà hàng hỗ trợ chuẩn bị mâm lễ gia tiên (trái cây, xôi gà/heo quay, trầu cau, rượu trà...) và có thể tư vấn nghi thức truyền thống phù hợp phong tục từng vùng miền.",tag:"gia_tien"},
{id:84,cat:"G",q:"Nhà hàng có cho thuê áo dài, vest, trang phục cưới không?",v:["Có thuê áo dài không ạ?"],a:"Dạ hiện dịch vụ chính của nhà hàng tập trung vào nhà hàng, nấu tiệc, gia tiên, mâm quả và decor. Về trang phục cưới, vui lòng liên hệ hotline để nhà hàng tư vấn xem có đơn vị đối tác hỗ trợ hay không.",tag:"cho_thue_trang_phuc"},
{id:85,cat:"G",q:"Nhà hàng có dịch vụ chụp ảnh/quay phim cưới không?",v:["Có ekip quay chụp không ạ?"],a:"Dạ vui lòng liên hệ hotline để nhà hàng tư vấn cụ thể, hiện tại nhà hàng có thể hỗ trợ giới thiệu/liên kết đơn vị chụp ảnh, quay phim theo yêu cầu.",tag:"chup_anh_quay_phim"},
{id:86,cat:"G",q:"Nhà hàng có cung cấp MC dẫn chương trình tiệc cưới không?",v:["Có MC cho tiệc cưới không?"],a:"Dạ nhà hàng có thể hỗ trợ hoặc giới thiệu MC dẫn chương trình cho lễ cưới nếu gia đình có nhu cầu.",tag:"mc_dan_chuong_trinh"},
{id:87,cat:"G",q:"Có tổ chức được lễ đón dâu/rước dâu không?",v:["Có làm luôn lễ rước dâu không?"],a:"Dạ nhà hàng linh hoạt theo nhu cầu: có thể chỉ đặt tiệc đãi khách tại nhà hàng, hoặc sử dụng trọn gói bao gồm cả hỗ trợ chuẩn bị lễ gia tiên/mâm quả cho phần lễ tại nhà riêng.",tag:"le_ruoc_dau"},
{id:88,cat:"G",q:"Đặt trọn gói có được giảm giá so với đặt lẻ từng dịch vụ không?",v:["Đặt gói trọn có rẻ hơn không?"],a:"Dạ thông thường đặt trọn gói sẽ được nhà hàng ưu tiên hỗ trợ giá tốt hơn so với đặt lẻ từng phần, đồng thời anh/chị cũng đỡ mất công liên hệ nhiều nơi.",tag:"uu_dai_tron_goi"},
{id:89,cat:"G",q:"Thời gian chuẩn bị cho 1 tiệc cưới trọn gói mất bao lâu?",v:["Chuẩn bị tiệc mất mấy ngày?"],a:"Dạ thời gian chuẩn bị tùy quy mô tiệc, thông thường nhà hàng khuyến khích đặt trước 1–3 tháng để có đủ thời gian lên thực đơn, chuẩn bị mâm quả, gia tiên và trang trí chỉn chu nhất.",tag:"thoi_gian_chuan_bi"},
{id:90,cat:"G",q:"Có tư vấn kịch bản/timeline chương trình tiệc cưới không?",v:["Có lên timeline chương trình không?"],a:"Dạ có ạ, nhân viên phụ trách sẽ trao đổi và hỗ trợ lên timeline chương trình tiệc (giờ đón khách, giờ làm lễ, phát biểu, khai tiệc...) để buổi tiệc diễn ra trơn tru, đúng giờ.",tag:"timeline_chuong_trinh"},
{id:91,cat:"G",q:"Nhà hàng có tổ chức lễ hỏi riêng biệt với đám cưới không?",v:["Đám hỏi có tổ chức riêng được không?"],a:"Dạ được ạ, nhà hàng nhận tổ chức riêng lễ ăn hỏi (đám hỏi) với mâm quả, tiệc nhỏ gọn phù hợp, không nhất thiết phải đi kèm tiệc cưới lớn.",tag:"to_chuc_dam_hoi"},
{id:92,cat:"G",q:"Có hỗ trợ in thiệp cưới, sổ mừng cưới không?",v:["Có in thiệp cưới không ạ?"],a:"Dạ nhà hàng có thể hỗ trợ chuẩn bị bàn tiếp khách, sổ mừng cưới cơ bản; riêng phần in thiệp cưới nên đặt sớm ở đơn vị in ấn để đảm bảo kịp thời gian gửi khách mời.",tag:"thiep_cuoi_so_mung"},
{id:93,cat:"G",q:"Nhà hàng có phục vụ tiệc chia tay/tân hôn sau đám cưới không?",v:["Có làm tiệc lại mặt không?"],a:"Dạ có ạ, ngoài tiệc cưới chính, nhà hàng cũng nhận tổ chức các buổi tiệc liên quan như lại mặt, tân hôn, họp mặt gia đình hai bên với quy mô nhỏ gọn theo yêu cầu.",tag:"tiec_lai_mat"},
{id:94,cat:"H",q:"Muốn đổi ngày tổ chức tiệc sang ngày khác thì có được không?",v:["Dời ngày cưới có được không?"],a:"Dạ anh/chị có thể đổi ngày tổ chức, tuy nhiên nên báo cho nhà hàng càng sớm càng tốt để kiểm tra lịch trống ngày mới còn phù hợp không.",tag:"doi_lich_to_chuc"},
{id:95,cat:"H",q:"Nếu hủy tiệc gấp sát ngày tổ chức thì xử lý thế nào?",v:["Hủy gấp trước 1 ngày có được không?"],a:"Dạ trường hợp hủy sát ngày tổ chức, do nhà hàng đã chuẩn bị nguyên liệu và sắp xếp nhân sự, có thể sẽ áp dụng chính sách không hoàn cọc hoặc phụ thu tùy tình huống cụ thể. Vui lòng liên hệ hotline ngay khi có thay đổi để được hỗ trợ tốt nhất.",tag:"huy_gap_sat_ngay"},
{id:96,cat:"H",q:"Nếu trời mưa bão ảnh hưởng đến tiệc thì nhà hàng có hỗ trợ gì không?",v:["Bão đến ngày cưới thì sao ạ?"],a:"Dạ trong trường hợp bất khả kháng như mưa bão, thiên tai, nhà hàng sẽ linh động hỗ trợ dời lịch hoặc tư vấn phương án phù hợp nhất cho gia đình.",tag:"bat_kha_khang"},
{id:97,cat:"H",q:"Nếu số lượng khách đến thực tế đông hơn dự kiến thì có sắp xếp thêm bàn được không?",v:["Khách đến đông hơn dự tính thì sao?"],a:"Dạ nhà hàng sẽ cố gắng linh động sắp xếp thêm bàn ngay trong khả năng cho phép. Để chủ động hơn, nên báo trước số bàn dự phòng khi đặt tiệc.",tag:"khach_dong_hon_du_kien"},
{id:98,cat:"H",q:"Nếu món ăn giao không đúng như đã thỏa thuận thì xử lý thế nào?",v:["Món ăn không đúng như đặt thì sao?"],a:"Dạ nếu có sai sót về món ăn so với thỏa thuận, vui lòng phản ánh ngay với nhân viên phụ trách tại tiệc hoặc qua hotline để nhà hàng kiểm tra và xử lý, bổ sung kịp thời.",tag:"khieu_nai_mon_an"},
{id:99,cat:"H",q:"Có thể yêu cầu đổi khu vực tổ chức sau khi đã đặt không?",v:["Đổi từ trong nhà ra ngoài rạp được không?"],a:"Dạ được ạ, miễn là khu vực còn trống vào thời điểm tiệc của mình, cứ báo trước cho nhà hàng để được sắp xếp và xác nhận lại khu vực tổ chức phù hợp.",tag:"doi_khu_vuc_to_chuc"},
{id:100,cat:"H",q:"Nếu chương trình tiệc bị trễ giờ thì nhà hàng có tính thêm phí không?",v:["Tiệc kéo dài hơn dự kiến có tính thêm tiền không?"],a:"Dạ nếu tiệc kéo dài hơn so với thời gian đã thỏa thuận ban đầu (thêm giờ, thêm nhân sự), có thể phát sinh phụ thu tương ứng. Nhà hàng sẽ trao đổi rõ nếu có phát sinh này.",tag:"phu_thu_tre_gio"},
{id:101,cat:"H",q:"Có được đổi người đứng tên đặt tiệc không?",v:["Đổi người đại diện đặt tiệc có được không?"],a:"Dạ được ạ, chỉ cần thông báo cho nhà hàng biết thông tin người đại diện mới để cập nhật và liên hệ thuận tiện hơn trong quá trình chuẩn bị tiệc.",tag:"doi_nguoi_dai_dien"},
{id:102,cat:"H",q:"Nếu có vấn đề phát sinh trong lúc diễn ra tiệc thì liên hệ ai để xử lý ngay?",v:["Đang tiệc có vấn đề thì gọi ai?"],a:"Dạ trong suốt buổi tiệc sẽ luôn có nhân viên/quản lý trực tiếp tại nhà hàng hỗ trợ, cứ báo trực tiếp cho nhân viên phục vụ hoặc nhân viên phụ trách tiệc để được xử lý nhanh chóng.",tag:"xu_ly_su_co_tai_cho"},
{id:103,cat:"H",q:"Chính sách bảo mật thông tin khách hàng như thế nào?",v:["Thông tin em có được bảo mật không?"],a:"Dạ nhà hàng cam kết chỉ sử dụng thông tin được cung cấp để phục vụ cho việc chuẩn bị và liên hệ đặt tiệc, không chia sẻ cho bên thứ ba ngoài mục đích tổ chức tiệc.",tag:"bao_mat_thong_tin"},
{id:104,cat:"I",q:"Nhà hàng có chỗ đậu xe ô tô, xe khách không?",v:["Có bãi đậu xe không ạ?"],a:"Dạ nhà hàng có khu vực đỗ xe cho khách đến dự tiệc, kể cả xe ô tô cá nhân. Với đoàn xe lớn/xe khách nên báo trước số lượng xe.",tag:"bai_dau_xe"},
{id:105,cat:"I",q:"Từ trung tâm thị xã Vạn Ninh đến nhà hàng bao xa?",v:["Đi từ trung tâm Vạn Ninh mất bao lâu?"],a:"Dạ nhà hàng nằm tại Thôn Ninh Mã, xã Đại Lãnh, tỉnh Khánh Hòa. Anh/chị có thể dùng Google Maps tìm \"Nhà Hàng Tiệc Cưới Thiện Nga\" để xem quãng đường và thời gian di chuyển chính xác.",tag:"khoang_cach_di_chuyen"},
{id:106,cat:"I",q:"Có gần quốc lộ/đường lớn để dễ tìm không?",v:["Đường vào có dễ đi không?"],a:"Dạ khu vực Đại Lãnh, Vạn Ninh nằm gần tuyến đường chính, khá thuận tiện di chuyển bằng ô tô/xe máy.",tag:"duong_di_thuan_tien"},
{id:107,cat:"I",q:"Có hỗ trợ xe đưa đón khách ở xa đến dự tiệc không?",v:["Có xe đưa đón không ạ?"],a:"Dạ hiện nhà hàng chưa có dịch vụ xe đưa đón riêng, anh/chị có thể chủ động sắp xếp phương tiện hoặc liên hệ hotline để được tư vấn thêm.",tag:"xe_dua_don"},
{id:108,cat:"I",q:"Xung quanh nhà hàng có chỗ nghỉ ngơi/khách sạn cho khách ở xa không?",v:["Gần đây có nhà nghỉ khách sạn không?"],a:"Dạ khu vực Vạn Ninh – Đại Lãnh có một số nhà nghỉ, khách sạn gần biển, anh/chị có thể tìm kiếm thêm trên Google Maps hoặc liên hệ hotline để được gợi ý.",tag:"cho_o_gan_do"},
{id:109,cat:"I",q:"Đường đi có phù hợp cho xe hoa/đoàn rước dâu di chuyển không?",v:["Đoàn xe hoa vào tận nơi được không?"],a:"Dạ được ạ, đường vào khu vực nhà hàng đủ rộng cho đoàn xe hoa/rước dâu di chuyển và có khu vực đỗ xe tạm cho đoàn trong lúc diễn ra lễ.",tag:"duong_cho_xe_hoa"},
{id:110,cat:"I",q:"Nhà hàng có ở gần biển không, có thể tổ chức tiệc ngoài trời view biển không?",v:["Có view biển không ạ?"],a:"Dạ khu vực Đại Lãnh, Vạn Ninh nằm gần biển, không gian thoáng đãng rất thích hợp cho tiệc cưới ngoài trời. Liên hệ hotline để được tư vấn thêm về vị trí và góc trang trí đẹp nhất.",tag:"view_bien"},
{id:111,cat:"I",q:"Có thể gửi định vị Google Maps chính xác không?",v:["Cho xin link Google Maps với ạ"],a:"Dạ anh/chị vào nhahangthiennga.com, bấm nút \"Mở Google Maps\"/\"Chỉ đường\" ở phần địa chỉ Cơ sở Đại Lãnh để lấy định vị chính xác, hoặc nhắn hotline để gửi trực tiếp link bản đồ.",tag:"link_google_maps"},
{id:112,cat:"J",q:"Hiện tại nhà hàng có chương trình khuyến mãi gì không?",v:["Có ưu đãi gì hiện tại không ạ?"],a:"Dạ nhà hàng thường xuyên có các chương trình ưu đãi, minigame nhận mã giảm giá (như minigame \"Lắc xí ngầu\" trên website) và ưu đãi theo mùa cưới. Theo dõi Fanpage hoặc hotline để cập nhật chương trình mới nhất.",tag:"khuyen_mai_hien_tai"},
{id:113,cat:"J",q:"Minigame \"Lắc xí ngầu\" trên website chơi như thế nào?",v:["Minigame lắc xí ngầu là gì?"],a:"Dạ trên website có minigame \"Lắc xí ngầu\": khách lắc 3 hột xí ngầu, nếu ra \"Tài\" (tổng từ 11 trở lên) là trúng ưu đãi. Sau khi trúng, hoàn tất khảo sát ngắn để nhận mã ưu đãi áp dụng khi đặt tiệc/đặt bàn.",tag:"minigame_lac_xi_ngau"},
{id:114,cat:"J",q:"Đặt tiệc sớm có được ưu đãi gì không?",v:["Đặt sớm có giảm giá không?"],a:"Dạ việc đặt tiệc sớm giúp anh/chị chắc chắn giữ được ngày đẹp và có thời gian chuẩn bị chu đáo. Về ưu đãi cụ thể cho khách đặt sớm, liên hệ hotline để được cập nhật chương trình đang áp dụng.",tag:"uu_dai_dat_som"},
{id:115,cat:"J",q:"Có ưu đãi dành cho khách hàng cũ/giới thiệu khách mới không?",v:["Khách quen có giảm giá không?"],a:"Dạ nhà hàng luôn trân trọng khách hàng thân thiết và khách được giới thiệu, liên hệ hotline để được tư vấn ưu đãi dành riêng cho trường hợp này nếu chương trình đang áp dụng.",tag:"uu_dai_khach_quen"},
{id:116,cat:"J",q:"Vào các dịp lễ đặc biệt có chương trình gì không?",v:["Lễ Valentine có ưu đãi gì không?"],a:"Dạ vào các dịp lễ đặc biệt, nhà hàng thường có chương trình ưu đãi/trang trí theo chủ đề riêng. Theo dõi Fanpage hoặc liên hệ hotline gần ngày lễ để cập nhật.",tag:"uu_dai_dip_le"},
{id:117,cat:"J",q:"Mã ưu đãi nhận được từ minigame có áp dụng cho mọi loại tiệc không?",v:["Mã giảm giá dùng cho tiệc nào cũng được không?"],a:"Dạ điều kiện áp dụng mã ưu đãi sẽ được ghi rõ khi nhận mã sau minigame, thường áp dụng khi đặt bàn/đặt tiệc trong thời gian mã còn hiệu lực.",tag:"dieu_kien_ap_dung_ma"},
{id:118,cat:"J",q:"Có chương trình tích điểm cho khách đặt tiệc nhiều lần không?",v:["Đặt nhiều lần có tích điểm không?"],a:"Dạ hiện nhà hàng chưa triển khai hệ thống tích điểm chính thức, tuy nhiên khách hàng thân thiết luôn được ưu tiên hỗ trợ và tư vấn tận tình trong mỗi lần đặt tiệc.",tag:"tich_diem"},
{id:119,cat:"J",q:"Ưu đãi có áp dụng đồng thời với giảm giá theo số lượng bàn không?",v:["Ưu đãi minigame cộng dồn với giảm giá số lượng được không?"],a:"Dạ việc cộng dồn nhiều chương trình ưu đãi cùng lúc sẽ tùy theo quy định cụ thể của từng chương trình tại thời điểm áp dụng, liên hệ hotline để được tư vấn chính xác nhất.",tag:"cong_don_uu_dai"},
{id:120,cat:"K",q:"Nhà hàng có nhận tổ chức tiệc sinh nhật không?",v:["Làm sinh nhật cho bé được không ạ?"],a:"Dạ có ạ, nhà hàng nhận tổ chức tiệc sinh nhật cho cả trẻ em và người lớn, có thể kết hợp trang trí bóng bay, bánh kem theo yêu cầu.",tag:"tiec_sinh_nhat"},
{id:121,cat:"K",q:"Nhà hàng có nhận tổ chức hội nghị, họp mặt công ty không?",v:["Họp mặt cuối năm công ty được không?"],a:"Dạ có ạ, nhà hàng nhận tổ chức tiệc hội nghị, họp mặt, liên hoan công ty với không gian rộng rãi và thực đơn linh hoạt theo ngân sách.",tag:"hoi_nghi_hop_mat"},
{id:122,cat:"K",q:"Có nhận đặt tiệc tất niên, liên hoan cuối năm không?",v:["Liên hoan cuối năm đặt sớm được không?"],a:"Dạ có ạ, tuy nhiên vào dịp cuối năm lượng khách đặt tiệc tất niên/liên hoan rất đông, nên liên hệ đặt lịch sớm để đảm bảo có chỗ.",tag:"tiec_tat_nien"},
{id:123,cat:"K",q:"Có nhận đặt tiệc thôi nôi, đầy tháng cho bé không?",v:["Làm tiệc đầy tháng cho con được không?"],a:"Dạ có ạ, nhà hàng nhận tổ chức tiệc thôi nôi, đầy tháng với không gian ấm cúng, có thể hỗ trợ trang trí theo chủ đề bé trai/bé gái.",tag:"tiec_thoi_noi"},
{id:124,cat:"K",q:"Khách đi ăn thường ngày có cần đặt bàn trước không?",v:["Nhóm bạn đi nhậu có cần báo trước không?"],a:"Dạ với nhóm nhỏ có thể ghé trực tiếp; tuy nhiên vào cuối tuần hoặc giờ cao điểm, nên gọi trước hotline để nhà hàng giữ bàn, tránh phải chờ lâu.",tag:"dat_ban_an_thuong"},
{id:125,cat:"K",q:"Nhà hàng có phục vụ tiệc gia đình nhỏ (dưới 10 người) không?",v:["Nhóm nhỏ đặt bàn được không?"],a:"Dạ có ạ, nhà hàng phục vụ linh hoạt từ tiệc gia đình nhỏ đến tiệc lớn, cứ liên hệ đặt bàn theo nhu cầu thực tế của mình.",tag:"tiec_gia_dinh_nho"},
{id:126,cat:"K",q:"Có nhận đặt tiệc cho đoàn khách du lịch không?",v:["Đoàn du lịch ghé ăn được không?"],a:"Dạ có ạ, nhà hàng có kinh nghiệm phục vụ đoàn khách đông (kể cả khách du lịch), liên hệ hotline trước để sắp xếp bàn và chuẩn bị thực đơn phù hợp số lượng đoàn.",tag:"doan_khach_du_lich"},
{id:127,cat:"K",q:"Nhà hàng có giao đồ ăn/đặt tiệc online qua ứng dụng giao đồ ăn không?",v:["Có trên GrabFood/ShopeeFood không?"],a:"Dạ hiện tại cách đặt nhanh và chính xác nhất là liên hệ trực tiếp hotline hoặc nhắn tin Fanpage/website của nhà hàng.",tag:"dat_qua_app"},
{id:128,cat:"K",q:"Nhà hàng có phục vụ tiệc buffet không hay chỉ phục vụ theo mâm/set?",v:["Ăn tự chọn được không?"],a:"Dạ hình thức phục vụ chính của nhà hàng là theo mâm/set thực đơn cố định. Muốn hình thức buffet cho sự kiện đặc biệt thì liên hệ hotline để trao đổi khả năng đáp ứng.",tag:"tiec_buffet"},
{id:129,cat:"L",q:"Nhà hàng có đảm bảo vệ sinh an toàn thực phẩm không?",v:["Có giấy chứng nhận VSATTP không?"],a:"Dạ nhà hàng luôn chú trọng vệ sinh an toàn thực phẩm trong khâu chọn nguyên liệu tươi sống và chế biến, đảm bảo an toàn cho khách hàng trong mỗi bữa tiệc.",tag:"vsattp"},
{id:130,cat:"L",q:"Nếu khách bị ngộ độc/dị ứng sau khi ăn thì nhà hàng xử lý ra sao?",v:["Lỡ có sự cố về sức khỏe sau khi ăn thì sao?"],a:"Dạ đây là tình huống nhà hàng luôn cố gắng phòng tránh tối đa bằng việc kiểm soát chất lượng nguyên liệu và chế biến. Nếu không may xảy ra, vui lòng liên hệ ngay hotline để nhà hàng phối hợp hỗ trợ xử lý kịp thời.",tag:"xu_ly_ngo_doc"},
{id:131,cat:"L",q:"Có thể yêu cầu nấu nhạt/ít cay cho người lớn tuổi không?",v:["Người già ăn nhạt được không?"],a:"Dạ được ạ, nhà hàng có thể điều chỉnh gia vị (nhạt hơn, ít cay, ít dầu mỡ) cho một số mâm dành riêng cho người lớn tuổi nếu báo trước nhu cầu này.",tag:"mon_nguoi_lon_tuoi"},
{id:132,cat:"L",q:"Nhân viên phục vụ có được đào tạo về an toàn vệ sinh không?",v:["Nhân viên có được tập huấn VSATTP không?"],a:"Dạ đội ngũ nhân viên nhà hàng được hướng dẫn quy trình vệ sinh trong chế biến và phục vụ nhằm đảm bảo an toàn cho khách hàng.",tag:"dao_tao_nhan_vien"},
{id:133,cat:"L",q:"Nước đá, nước uống tại nhà hàng có đảm bảo vệ sinh không?",v:["Nước đá có sạch không ạ?"],a:"Dạ nhà hàng sử dụng nguồn nước đá và nước uống đảm bảo vệ sinh để phục vụ khách hàng an tâm trong suốt bữa tiệc.",tag:"nuoc_da_ve_sinh"},
{id:134,cat:"L",q:"Nhà hàng có khu vực riêng cho người khuyết tật/người già di chuyển khó khăn không?",v:["Có lối đi cho xe lăn không?"],a:"Dạ vui lòng báo trước nếu gia đình có người lớn tuổi hoặc di chuyển khó khăn, nhà hàng sẽ ưu tiên sắp xếp bàn ở vị trí thuận tiện, gần lối ra vào nhất có thể.",tag:"ho_tro_nguoi_gia"},
{id:135,cat:"L",q:"Có cần báo trước số lượng khách ăn chay/dị ứng để chuẩn bị không?",v:["Cần báo trước bao nhiêu suất chay?"],a:"Dạ nên báo số lượng suất chay hoặc thông tin dị ứng trước ít nhất 2–3 ngày trước tiệc để nhà hàng chuẩn bị nguyên liệu và chế biến riêng chu đáo, đảm bảo an toàn.",tag:"bao_truoc_suat_dac_biet"},
{id:136,cat:"L",q:"Thức ăn thừa/nguyên liệu có được nhà hàng bảo quản đúng cách không?",v:["Nguyên liệu bảo quản có đảm bảo không?"],a:"Dạ nhà hàng tuân thủ quy trình bảo quản nguyên liệu (đặc biệt hải sản tươi sống) trong tủ lạnh/tủ đông đúng cách để đảm bảo tươi ngon và an toàn khi chế biến.",tag:"bao_quan_nguyen_lieu"},
{id:137,cat:"L",q:"Nhà hàng có phục vụ khách nước ngoài (menu tiếng Anh) không?",v:["Có menu tiếng Anh không ạ?"],a:"Dạ nhà hàng vẫn phục vụ khách nước ngoài bình thường, hiện thực đơn chính bằng tiếng Việt. Nếu cần hỗ trợ thêm về ngôn ngữ, vui lòng liên hệ hotline để nhà hàng sắp xếp hỗ trợ.",tag:"menu_tieng_anh"},
{id:138,cat:"L",q:"Có yêu cầu đặc biệt nào nhà hàng không thể đáp ứng không?",v:["Có món/yêu cầu nào quán không làm được không?"],a:"Dạ hầu hết các yêu cầu về thực đơn, trang trí, quy mô tiệc nhà hàng đều cố gắng đáp ứng linh hoạt. Yêu cầu đặc biệt/phức tạp, cứ trao đổi trực tiếp qua hotline để xác nhận khả năng thực hiện cụ thể.",tag:"yeu_cau_dac_biet"},
{id:139,cat:"M",q:"Muốn khiếu nại về chất lượng dịch vụ thì liên hệ ở đâu?",v:["Khiếu nại thì gọi đâu ạ?"],a:"Dạ anh/chị vui lòng phản ánh trực tiếp qua hotline 0965 626 128 hoặc nhắn tin Fanpage Facebook, mọi góp ý sẽ được tiếp nhận và phản hồi xử lý sớm nhất để phục vụ tốt hơn.",tag:"khieu_nai"},
{id:140,cat:"M",q:"Sau khi đặt tiệc, bao lâu thì được phản hồi tư vấn?",v:["Nhắn tin bao lâu thì trả lời vậy?"],a:"Dạ nhà hàng cố gắng phản hồi tin nhắn/cuộc gọi trong thời gian sớm nhất trong giờ hoạt động. Cần gấp, nên gọi trực tiếp hotline để được hỗ trợ nhanh nhất.",tag:"thoi_gian_phan_hoi"},
{id:141,cat:"M",q:"Có thể góp ý về món ăn/dịch vụ sau khi dùng tiệc không?",v:["Ăn xong có được góp ý không?"],a:"Dạ nhà hàng rất trân trọng mọi góp ý của khách hàng, có thể để lại đánh giá trên Fanpage Facebook hoặc nhắn trực tiếp hotline sau khi dùng tiệc.",tag:"gop_y_danh_gia"},
{id:142,cat:"M",q:"Nhân viên tư vấn có hỗ trợ ngoài giờ hành chính không?",v:["Buổi tối nhắn tin có ai trả lời không?"],a:"Dạ nhà hàng hoạt động cả cuối tuần nên vẫn có thể hỗ trợ tư vấn ngoài giờ hành chính, tuy nhiên để chắc chắn được phản hồi nhanh, nên gọi trực tiếp hotline vào các khung giờ thuận tiện.",tag:"ho_tro_ngoai_gio"},
{id:143,cat:"M",q:"Có thể trao đổi qua Zalo không hay chỉ qua điện thoại/Facebook?",v:["Có Zalo không ạ?","Cho xin Zalo với ạ"],a:"Dạ có ạ, anh/chị có thể nhắn Zalo trực tiếp qua https://zalo.me/0965626128 để được tư vấn nhanh, hoặc gọi hotline/nhắn Fanpage Facebook đều được.",tag:"kenh_zalo"},
{id:144,cat:"M",q:"Nếu không hài lòng có được hoàn tiền một phần không?",v:["Dịch vụ tệ có được bồi hoàn không?"],a:"Dạ nhà hàng luôn ưu tiên xử lý thỏa đáng khi có sự cố ngoài mong muốn, mức hỗ trợ/hoàn tiền (nếu có) sẽ tùy tình huống cụ thể sau khi nhà hàng xác minh. Vui lòng phản ánh chi tiết qua hotline để được xem xét và hỗ trợ.",tag:"hoan_tien_khieu_nai"},
{id:145,cat:"M",q:"Có kênh nào để theo dõi tình trạng xử lý khiếu nại không?",v:["Gửi phản ánh rồi theo dõi kết quả ở đâu?"],a:"Dạ sau khi tiếp nhận phản ánh, nhân viên phụ trách sẽ chủ động liên hệ lại qua số điện thoại đã cung cấp để thông báo tiến độ và kết quả xử lý.",tag:"theo_doi_khieu_nai"},
{id:146,cat:"M",q:"Có thể đặt lịch tư vấn trực tiếp với quản lý nhà hàng không?",v:["Gặp trực tiếp quản lý được không?"],a:"Dạ được ạ, với các yêu cầu đặc biệt hoặc tiệc quy mô lớn, anh/chị có thể đề nghị nhân viên tư vấn sắp xếp cuộc hẹn trao đổi trực tiếp với quản lý nhà hàng.",tag:"gap_quan_ly"},
{id:147,cat:"N",q:"chào hỏi mở đầu",v:["chào shop","cho hỏi","alo","xin chào","chào ạ","hi","hello"],a:"Dạ em chào anh/chị, em là trợ lý tư vấn của Nhà Hàng Tiệc Cưới Thiện Nga ạ! Anh/chị cần tư vấn đặt tiệc cưới, đặt bàn ăn uống hay thông tin thực đơn/giá cả ạ? Em hỗ trợ mình ngay đây ạ.",tag:"greeting"},
{id:148,cat:"N",q:"câu hỏi ngoài phạm vi",v:["hôm nay thời tiết thế nào","kể chuyện cười đi","1+1 bằng mấy"],a:"Dạ em là trợ lý hỗ trợ tư vấn dịch vụ tiệc cưới – nhà hàng của Thiện Nga nên câu hỏi này em chưa hỗ trợ được ạ. Anh/chị cần tư vấn gì về đặt tiệc, thực đơn hay giá cả không ạ, em hỗ trợ ngay nhé.",tag:"out_of_scope"},
{id:149,cat:"N",q:"muốn gặp nhân viên thật",v:["cho gặp nhân viên","tư vấn viên thật đâu","nói chuyện với người thật được không"],a:"Dạ được ạ, anh/chị vui lòng để lại số điện thoại hoặc gọi trực tiếp hotline 0965 626 128, nhân viên tư vấn của nhà hàng sẽ liên hệ hỗ trợ anh/chị ngay ạ.",tag:"chuyen_nhan_vien"},
{id:150,cat:"N",q:"hỏi giá chung chung",v:["giá bao nhiêu","nhiêu tiền","bao nhiêu vậy"],a:"Dạ để tư vấn giá chính xác nhất, anh/chị cho em xin thêm thông tin: mình muốn hỏi giá món ăn lẻ, giá theo bàn tiệc hay giá trọn gói cưới hỏi ạ? Và anh/chị dự kiến tổ chức khoảng bao nhiêu bàn/khách ạ?",tag:"hoi_lai_lam_ro"},
{id:151,cat:"N",q:"xác nhận muốn đặt tiệc",v:["ok đặt luôn","chốt đặt tiệc nha","vậy đặt giúp mình nha"],a:"Dạ em cảm ơn anh/chị đã tin tưởng Thiện Nga ạ! Anh/chị cho em xin: họ tên, số điện thoại, ngày giờ tổ chức, số bàn dự kiến để em chuyển thông tin cho nhân viên phụ trách xác nhận và hướng dẫn đặt cọc giữ chỗ ạ.",tag:"chot_don"},
{id:152,cat:"N",q:"cảm ơn kết thúc",v:["cảm ơn nha","ok cảm ơn em","vậy thôi nha"],a:"Dạ em cảm ơn anh/chị rất nhiều ạ! Nếu cần hỗ trợ thêm bất cứ lúc nào, anh/chị cứ nhắn lại cho em nhé. Chúc anh/chị một ngày thật vui, chúc mừng hạnh phúc/chúc buổi tiệc thành công tốt đẹp ạ!",tag:"closing"},
{id:153,cat:"N",q:"phàn nàn bức xúc",v:["dịch vụ tệ quá","sao chậm trễ vậy","tôi rất không hài lòng"],a:"Dạ em thành thật xin lỗi vì trải nghiệm chưa tốt đã làm phiền lòng anh/chị. Em xin phép ghi nhận thông tin để chuyển ngay đến quản lý/nhân viên phụ trách xử lý ạ. Anh/chị vui lòng cho em xin số điện thoại và mô tả cụ thể vấn đề để được hỗ trợ nhanh nhất ạ.",tag:"phan_nan"},
{id:154,cat:"N",q:"hỏi giờ hoạt động chatbot",v:["mấy giờ có người trực vậy","chatbot hoạt động giờ nào"],a:"Dạ em (trợ lý tự động) hỗ trợ trả lời 24/7 các câu hỏi thường gặp ạ. Với các yêu cầu cần nhân viên trực tiếp xử lý, nhà hàng sẽ phản hồi trong giờ hoạt động hằng ngày (08:00–20:00) ạ.",tag:"gio_hoat_dong_chatbot"},
{id:155,cat:"N",q:"gửi hình concept trang trí",v:["cho xem mẫu trang trí giống hình này được không","gửi hình concept muốn làm giống vậy"],a:"Dạ anh/chị gửi hình ảnh/ý tưởng mẫu qua đây, em sẽ chuyển cho bộ phận trang trí xem xét và tư vấn khả năng thực hiện cũng như báo giá phù hợp với concept mong muốn ạ.",tag:"gui_hinh_concept"},
{id:156,cat:"O",q:"40 Thực đơn cưới trọn gói là gì?",v:["40 thực đơn cưới là sao?","Thực đơn cưới trọn gói gồm những gì?"],a:"Dạ, đây là bộ 40 thực đơn tiệc cưới đã được Thiện Nga phối sẵn, mỗi thực đơn gồm 6 món cho 1 bàn 10 người: 1 Khai vị + 3 Món chính + 1 Món lẩu + 1 Tráng miệng, chia thành 3 mức giá để dễ lựa chọn theo ngân sách. Xem đầy đủ tại mục Thực Đơn Cưới trên nhahangthiennga.com.",tag:"gioi_thieu_40_thuc_don"},
{id:157,cat:"O",q:"3 mức giá của 40 thực đơn cưới chênh lệch nhau thế nào?",v:["Phổ thông, trung cấp, cao cấp khác gì nhau?"],a:"Dạ có 3 mức: Thực đơn Phổ Thông 2.200.000đ/bàn (10 thực đơn) – không có bào ngư, cá mú, giò heo, soup bồ câu/hàu; Thực đơn Trung Cấp 2.300.000đ/bàn (20 thực đơn) – có thể có soup bồ câu hạt sen, một số món cá/hải sản khá hơn; Thực đơn Cao Cấp 2.400.000đ/bàn (10 thực đơn) – luôn có nguyên liệu thượng hạng như bào ngư, cá mú, giò heo hảo hạng.",tag:"so_sanh_3_muc_gia"},
{id:158,cat:"O",q:"Có thể tự chọn món để ghép mâm riêng không?",v:["Tự ghép thực đơn riêng được không?","Có công cụ tự chọn món không?"],a:"Dạ có ạ, trên website có mục \"Tự Mix Menu Theo Ý Thích\": anh/chị tự chọn 1 Khai vị, 3 Món chính, 1 Lẩu và 1 Tráng miệng theo đúng cấu trúc 1 mâm tiệc 10 người như 40 thực đơn cưới, hệ thống sẽ tự tính giá dự kiến, sau đó bấm gọi hoặc nhắn Zalo để đặt luôn mâm vừa ghép.",tag:"tu_mix_menu"},
{id:159,cat:"O",q:"Công cụ tính giá mâm tiệc tự động có chính xác 100% không?",v:["Giá tự tính có đúng không?"],a:"Dạ giá hiển thị là giá dự kiến, được tính tự động dựa theo nhóm nguyên liệu của 3 mức giá thực đơn cưới hiện có. Để có báo giá chính xác 100%, vui lòng gọi hoặc nhắn Zalo để nhà hàng xác nhận lại trước khi đặt cọc.",tag:"do_chinh_xac_tinh_gia"},
{id:160,cat:"O",q:"Đặt tiệc cưới trọn gói qua Zalo như thế nào?",v:["Đặt qua Zalo có nhanh không?"],a:"Dạ rất tiện ạ, chỉ cần chọn 1 trong 40 thực đơn (hoặc tự mix), bấm nút \"Đặt menu\"/\"Nhắn Zalo đặt mâm này\" để mở Zalo https://zalo.me/0965626128, gửi thông tin ngày giờ, số bàn là nhà hàng sẽ tư vấn và xác nhận đặt tiệc ngay.",tag:"dat_qua_zalo"},
{id:161,cat:"O",q:"Có được tặng kèm gì khi đặt tiệc không?",v:["Nghe nói có tặng món khai vị đúng không?"],a:"Dạ đúng ạ, hiện nhà hàng có ưu đãi tặng kèm 1 món Khai Vị miễn phí để khách dùng trong lúc chờ vào tiệc chính, áp dụng khi đặt tiệc nấu tại gia/tiệc cưới qua nhahangthiennga.com.",tag:"tang_kem_khai_vi"},
{id:162,cat:"O",q:"Bàn 10 người là cố định hay có thể đặt bàn ít/nhiều người hơn?",v:["Bàn 8 người có được không?"],a:"Dạ mức giá 2.200.000–2.400.000đ được tính theo chuẩn 1 bàn 10 người. Nếu bàn có số người chênh lệch, nên báo trước để nhà hàng tư vấn điều chỉnh khẩu phần hoặc số bàn phù hợp, đảm bảo không thiếu không dư.",tag:"ban_10_nguoi"},
{id:163,cat:"P",q:"Thực đơn tổng của nhà hàng có tất cả bao nhiêu món để chọn?",v:["Menu tổng có nhiều món không?"],a:"Dạ thực đơn tổng của Thiện Nga có 100 món ăn, chia thành 9 nhóm: Khai Vị (25 món), Món Chính – Bò (16 món), Món Chính – Gà (11 món), Món Chính – Heo (9 món), Món Chính – Tôm & Mực (13 món), Món Chính – Cá (4 món), Món Chính Đặc Biệt Bào Ngư (4 món), Món Lẩu (13 món) và Tráng Miệng (5 món).",tag:"tong_quan_100_mon"},
{id:164,cat:"P",q:"Món Lẩu có bao nhiêu loại, món nào là đặc sản của vùng?",v:["Lẩu có mấy món?"],a:"Dạ nhóm Lẩu có 13 món: Lẩu Thái hải sản, Lẩu măng chua cá mú/cá bóp, Lẩu mực nấu é ớt xiêm xanh, Lẩu gà nấu lá giang... Trong đó Lẩu mực Đại Lãnh là món đặc sản mang đậm hương vị vùng biển Đại Lãnh – Khánh Hòa, rất được khách yêu thích.",tag:"chi_tiet_mon_lau"},
{id:165,cat:"P",q:"Xem hình ảnh thực tế của các món ở đâu?",v:["Có hình món ăn không?"],a:"Dạ xem thêm hình ảnh món ăn thực tế tại mục \"Album Món Ăn\" trên nhahangthiennga.com, hoặc trên Fanpage Facebook của nhà hàng.",tag:"xem_album_mon_an"},
{id:166,cat:"P",q:"Góc Bếp trên website là mục gì?",v:["Góc Bếp là gì vậy?"],a:"Dạ Góc Bếp là chuyên mục chia sẻ kinh nghiệm của Thiện Nga, ví dụ bài viết \"Kinh nghiệm đặt tiệc cưới tại nhà\", \"Cách chọn menu phù hợp ngân sách\"... rất hữu ích để tham khảo trước khi chọn thực đơn và trang trí cho tiệc của mình.",tag:"gioi_thieu_goc_bep"}
];

